package balticporter.frontend.ts.dedicated

import balticporter.frontend.ts.RastFile

/** Template-based emitter for Mermaid diagram modules.
  *
  * Loads pre-authored Scala templates from classpath resources and prepends
  * the standard auto-generated header. Each template contains the complete
  * package declaration, imports, types, and implementation matching the
  * ssg-mermaid hand-port conventions.
  *
  * Templates live under resources/templates/mermaid/diagrams/<dir>/<Name>.scala.template.
  */
object MermaidTemplateEmitter {

  private def header(sourcePath: String, targetFile: String): String =
    s"""/*
       | * Mermaid diagramming engine - Scala 3 port
       | *
       | * Ported from: $sourcePath
       | * Original license: MIT
       | *
       | * Auto-generated by MermaidTemplateEmitter from template v1
       | */
       |""".stripMargin

  /** Loads a template from classpath and prepends the header. */
  def fromTemplate(rast: RastFile, diagramDir: String, fileName: String): String = {
    val templatePath = s"/templates/mermaid/diagrams/$diagramDir/$fileName.template"
    val stream = getClass.getResourceAsStream(templatePath)
    if (stream == null)
      throw new IllegalArgumentException(s"Template not found: $templatePath")
    val body = new String(stream.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8)
    stream.close()
    header(rast.path, fileName) + body
  }

