  // Packet
  // ===========================================================================
  def emitPacketDb(rast: RastFile): String       = fromTemplate(rast, "packet", "PacketDb.scala")
  def emitPacketDiagram(rast: RastFile): String   = fromTemplate(rast, "packet", "PacketDiagram.scala")
  def emitPacketParser(rast: RastFile): String    = fromTemplate(rast, "packet", "PacketParser.scala")
  def emitPacketRenderer(rast: RastFile): String  = fromTemplate(rast, "packet", "PacketRenderer.scala")
  def emitPacketStyles(rast: RastFile): String    = fromTemplate(rast, "packet", "PacketStyles.scala")

